import React from "react";
import { Placeholder } from "react-bootstrap";

const PlaceholderStatistic = () => {
  return (
    <>
      <Placeholder as="p" animation="wave">
        <Placeholder xs={12} />
      </Placeholder>
    </>
  );
};

export default PlaceholderStatistic;
